fn push_arg_values(
    &self,
    arg: &Arg,
    raw_vals: Vec<OsString>,
    matcher: &mut ArgMatcher,
) -> ClapResult<()> {
    self.push_arg_values_with_parser(arg, raw_vals, matcher, arg.get_value_parser())
}

// Some actions (e.g. `SetTrue`, `SetFalse`, `Count`) synthesize their own values (like the
// implicit "false" default for `SetTrue`) that are unrelated to whatever the user provided on
// the command line.  In those cases, the `Arg`'s own `value_parser` (which may be a custom,
// user-supplied parser, e.g. one that always errors to suggest an alternative argument)
// shouldn't be applied; use `value_parser` explicitly instead.
fn push_arg_values_with_parser(
    &self,
    arg: &Arg,
    raw_vals: Vec<OsString>,
    matcher: &mut ArgMatcher,
    value_parser: &super::ValueParser,
) -> ClapResult<()> {
    debug!("Parser::push_arg_values: {raw_vals:?}");

    for raw_val in raw_vals {
        // update the current index because each value is a distinct index to clap
        self.cur_idx.set(self.cur_idx.get() + 1);
        debug!(
            "Parser::add_single_val_to_arg: cur_idx:={}",
            self.cur_idx.get()
        );
        let val = ok!(value_parser.parse_ref(self.cmd, Some(arg), &raw_val));

        matcher.add_val_to(arg.get_id(), val, raw_val);
        matcher.add_index_to(arg.get_id(), self.cur_idx.get());
    }

    Ok(())
}

